public class CotisationService : BaseApiService
{
  private const string BaseUrl = "/api/cotisations";

  public async Task<List<CotisationDto>> GetAllAsync()
  {
    return await GetAsync<List<CotisationDto>>(BaseUrl);
  }

  public async Task<CotisationDto> GetByIdAsync(long id)
  {
    return await GetAsync<CotisationDto>($"{BaseUrl}/{id}");
  }

  public async Task<CotisationDto> CreateAsync(CreateCotisationDto dto)
  {
    return await PostAsync<CotisationDto>(BaseUrl, dto);
  }

  public async Task<CotisationDto> UpdateAsync(long id, UpdateCotisationDto dto)
  {
    return await PutAsync<CotisationDto>($"{BaseUrl}/{id}", dto);
  }

  public async Task DeleteAsync(long id)
  {
    await DeleteAsync($"{BaseUrl}/{id}");
  }
}

